import {createJourneyUI} from './journey-ui.js';
import {seed,uid,money,today,totals,projectClient,invoiceStatus,createProject,acceptProposal,generateDeposit,recordPayment,suggestSetup,addActivity,migrate} from './domain.js';
const paths={leaf:'M12 21v-9c0-6 5-9 10-9 0 7-4 10-10 10M12 17C12 10 6 7 2 8c0 6 4 9 10 9',overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',clients:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',projects:'M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7z',invoices:'M6 3h9l4 4v14H5V3h1M14 3v5h5M8 12h8M8 16h5',workflows:'M6 3v6m0 6v6M6 9h9a3 3 0 0 1 3 3v3M3 9h6v6H3zM15 15h6v6h-6z',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',sparkles:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3M20 2v4M18 4h4',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',sun:'M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5l1.5 1.5M5 19l1.5-1.5M17.5 6.5l1.5-1.5M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',settings:'M4 7h16M4 17h16M8 4v6M16 14v6',money:'M12 3v18M17 7H9a3 3 0 0 0 0 6h6a3 3 0 0 1 0 6H6',download:'M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5',mail:'M3 5h18v14H3zM3 5l9 8 9-8',external:'M14 3h7v7M21 3 10 14M10 3H3v18h18v-7',calendar:'M4 5h16v16H4zM4 10h16M8 3v4M16 3v4',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.projects}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey='thrive-workspace-v1';
let state;try{state=migrate(JSON.parse(localStorage.getItem(storageKey)))}catch{state=seed()}
let page=location.hash.slice(1)||'overview',filter='all',query='',setupDraft,toastTimer;
try{document.documentElement.dataset.theme=localStorage.getItem('thrive-theme')||'dark'}catch{}
const dialog=document.querySelector('#dialog');
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state))}catch{toast('Browser storage is unavailable. Changes will last for this session.')}}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
function btn(text,action,extra='',cls=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`}
const badge=status=>`<span class="badge ${status.replaceAll(' ','-')}"><i></i>${esc(status)}</span>`;
const avatar=c=>`<span class="avatar ${c?.color||'sage'}">${esc(c?.initials||'?')}</span>`;
const date=s=>s?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z')):'No date';
function go(p){if(page===p){filter='all';query='';render()}else location.hash=p}
function open(title,html,{drawer=false,footer=''}={}){dialog.className=drawer?'drawer':'';dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${html}${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!dialog.open)dialog.showModal()}
function error(message){const e=dialog.querySelector('.form-error');if(e)e.textContent=message;else toast(message)}
function heading(title,description,action,eyebrow=''){return `<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${description}</p></div>${action||''}</div>`}
function shell(){
 const nav=[['overview','Overview'],['clients','Clients'],['projects','Projects'],['invoices','Invoices'],['workflows','Workflows']];
 document.querySelector('#sidebar').innerHTML=`<a href="#overview" class="brand" aria-label="Thrive home">${icon('leaf')}thrive</a><button class="workspace-switch" data-action="business"><span class="initial">${esc(state.settings.business.split(/\s+/).map(s=>s[0]).join('').slice(0,2))}</span><span><strong>${esc(state.settings.business)}</strong><small>Demo workspace</small></span>${icon('down')}</button><div class="nav-label">Workspace</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,label])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}${label}${id==='projects'?`<span class="count">${state.projects.filter(p=>!p.archived&&!['completed','cancelled','declined'].includes(p.status)).length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><button class="setup-link" data-action="setup">${icon('settings')}Workspace setup</button><div class="profile"><span class="avatar sand">${esc(state.settings.name.split(/\s+/).map(s=>s[0]).join('').slice(0,2))}</span><span><strong>${esc(state.settings.name)}</strong><small>Personal workspace</small></span><button class="icon-btn" data-action="theme" aria-label="Toggle light and dark theme">${icon('sun')}</button></div></div>`;
 document.querySelector('#topbar').innerHTML=`<div class="breadcrumb"><span>Workspace</span>${icon('chevron')}<span>${nav.find(n=>n[0]===page)?.[1]||'Overview'}</span></div><div class="top-actions"><span class="sample-pill"><i></i>Demo workspace</span><button class="search-btn" data-action="search" aria-label="Search workspace">${icon('search')}<span>Search anything</span><kbd>⌘ K</kbd></button><button class="icon-btn" data-action="theme" aria-label="Change appearance">${icon('sun')}</button></div>`;
}
function metrics(){const t=totals(state);return `<div class="stats"><div class="stat"><div class="stat-label">${icon('money')}Payments collected</div><div class="stat-value">${money(t.paid)}</div><div class="stat-note green">${state.invoices.filter(i=>i.paid>0).length} paid invoices · all time</div></div><div class="stat"><div class="stat-label">${icon('invoices')}Outstanding</div><div class="stat-value">${money(t.outstanding)}</div><div class="stat-note">${state.invoices.filter(i=>i.paid<i.amount).length} invoices awaiting payment</div></div><div class="stat"><div class="stat-label">${icon('clock')}Time tracked</div><div class="stat-value">${t.hours.toFixed(1)}<small>hrs</small></div><div class="stat-note">Total recorded hours</div></div><div class="stat"><div class="stat-label">${icon('projects')}Active projects</div><div class="stat-value">${String(t.active).padStart(2,'0')}</div><div class="stat-note">${state.projects.filter(p=>!p.archived&&['inquiry','proposal'].includes(p.status)).length} inquiries and proposals</div></div></div>`}
function projectRow(p){const c=projectClient(state,p);return `<button class="project-row" data-action="project" data-id="${p.id}">${avatar(c)}<span><span class="project-name">${esc(p.name)}</span><span class="project-sub">${esc(c.name)} <span class="muted">·</span> ${esc(p.service)}</span></span><span class="project-end">${p.needsPricing?'Not priced':money(p.budget)}<span class="progress-mini" aria-label="${p.phases.filter(f=>f.done).length} of ${p.phases.length} phases complete">${p.phases.map(f=>`<i class="${f.done?'done':''}"></i>`).join('')}</span></span></button>`}
function activity(){return `<div class="card"><div class="card-head"><h2>Recent activity</h2><span class="code-label">Activity log</span></div><div class="activity-list">${state.activity.slice(0,4).map(a=>`<div class="activity-row"><span class="activity-icon">${icon(a.kind==='payment'?'money':a.kind==='client'?'clients':'invoices')}</span><div><strong>${esc(a.text)}</strong><p>${esc(a.detail)}</p></div><time>${esc(a.time)}</time></div>`).join('')}</div></div>`}
function overview(){const active=state.projects.filter(p=>!p.archived&&!['completed','cancelled','declined'].includes(p.status)).slice(0,4);const proposal=state.projects.find(p=>!p.archived&&!p.accepted&&p.status==='proposal');const invoice=state.invoices.find(i=>invoiceStatus(i)==='overdue');return `${heading('Overview','Projects, payments, and tasks to review.',btn(icon('plus')+'New project','new-project','','primary'),'')}${metrics()}<div class="grid-main"><div class="left-col"><section class="card"><div class="card-head"><h2>Current projects <span class="num">${active.length}</span></h2><a class="text-btn" href="#projects">All projects ${icon('arrow')}</a></div>${active.map(projectRow).join('')}<div class="journey"><span>Project lifecycle</span>${icon('arrow')}<span>Inquiry</span>${icon('chevron')}<span>Agreement</span>${icon('chevron')}<span class="current">Delivery</span>${icon('chevron')}<span>Paid</span></div></section>${activity()}</div><div class="right-col"><section class="card"><div class="card-head"><h2>Needs attention</h2>${icon('sun')}</div><div class="attention">${proposal?`<div class="attention-item"><span class="mini-label"><i></i>READY FOR YOUR REVIEW</span><strong>${esc(projectClient(state,proposal).name)} proposal</strong><p>Review the scope and billing schedule.</p>${btn('Review proposal '+icon('arrow'),'proposal',`data-id="${proposal.id}"`)}</div>`:''}${invoice?`<div class="attention-item"><span class="mini-label"><i></i>PAYMENT TO FOLLOW UP</span><strong>${money(invoice.amount-invoice.paid)} from ${esc(projectClient(state,state.projects.find(p=>p.id===invoice.projectId)).name)}</strong><p>${invoice.number} · Due ${date(invoice.due)}</p>${btn('View invoice '+icon('arrow'),'invoice',`data-id="${invoice.id}"`)}</div>`:''}${!proposal&&!invoice?'<div class="attention-item"><strong>No pending actions.</strong><p>New review items will appear here.</p></div>':''}</div></section><section class="card ai-card"><div class="ai-card-body"><div class="ai-eyebrow">${icon('sparkles')} WORKSPACE SETUP</div><h2>Project defaults</h2><p>Set default phases, deposit terms, and proposal review.</p>${btn('Configure defaults '+icon('arrow'),'setup','','accent')}</div></section></div></div><div class="welcome-strip">${icon('leaf')}<div><strong>Inquiry form</strong><p>Collect project requests and create linked client records.</p></div><button class="text-btn" data-action="intake-preview">Preview inquiry form ${icon('arrow')}</button></div><div class="bottom-note">${icon('info')}You’re exploring sample data. Your changes are saved in this browser.</div>`}
function controls(tabs,placeholder){return `<div class="toolbar"><div class="tabs" aria-label="Filter">${tabs.map(([id,label])=>`<button class="tab ${filter===id?'active':''}" data-action="filter" data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><input class="filter-input" id="list-search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(query)}"></div>`}
function projectsPage(){let ps=state.projects.filter(p=>(filter==='archived'?p.archived:!p.archived&&(filter==='all'||p.status===filter))&&`${p.name} ${projectClient(state,p).name}`.toLowerCase().includes(query.toLowerCase()));return `${heading('Projects','Track inquiries, delivery, and billing.',btn(icon('plus')+'New project','new-project','','primary'))}${controls([['all','All projects'],['active','Active'],['inquiry','Inquiries'],['proposal','Proposals'],['completed','Completed'],['archived','Archived']],'Find a project…')}<div class="card table-wrap"><table class="data-table"><thead><tr><th>Project</th><th>Status</th><th>Fee</th><th>Phases</th><th>Target date</th></tr></thead><tbody>${ps.map(p=>{const c=projectClient(state,p);return `<tr><td><button class="name-cell" data-action="project" data-id="${p.id}">${avatar(c)}<span><strong>${esc(p.name)}</strong><small>${esc(c.name)}</small></span></button></td><td>${badge(p.archived?'archived':p.status)}</td><td>${p.needsPricing?'Not priced':money(p.budget)}</td><td><span class="muted">${p.phases.filter(f=>f.done).length} / ${p.phases.length} complete</span></td><td class="muted">${date(p.due)}</td></tr>`}).join('')}</tbody></table>${ps.length?'':'<div class="empty">No projects match this view.</div>'}</div><div class="footer-actions"><p>${ps.length} projects</p>${btn(icon('clock')+'Log time','log-time')}</div>`}
function clientsPage(){const cs=state.clients.filter(c=>(filter==='archived'?c.archived:!c.archived)&&`${c.name} ${c.contact} ${c.email}`.toLowerCase().includes(query.toLowerCase()));return `${heading('Clients','Manage contact details and client projects.',`<div class="heading-actions">${btn('Inquiry form','intake-builder')}${btn(icon('plus')+'New client','new-client','','primary')}</div>`)}${controls([['all',`Active clients · ${state.clients.filter(c=>!c.archived).length}`],['archived','Archived']],'Find a client…')}<div class="card table-wrap"><table class="data-table"><thead><tr><th>Client</th><th>Contact</th><th>Projects</th><th>Service</th></tr></thead><tbody>${cs.map(c=>`<tr><td><button class="name-cell" data-action="client" data-id="${c.id}">${avatar(c)}<span><strong>${esc(c.name)}</strong><small>${esc(c.email)}</small></span></button></td><td>${esc(c.contact)}</td><td>${state.projects.filter(p=>p.clientId===c.id).length}</td><td><span class="badge">${esc(c.tag)}</span></td></tr>`).join('')}</tbody></table>${cs.length?'':'<div class="empty">No clients match your search.</div>'}</div><div class="bottom-note">${icon('info')}Client details follow every project, proposal, and invoice.</div>`}
function invoicesPage(){const list=state.invoices.filter(i=>(filter==='all'||invoiceStatus(i)===filter)&&`${i.number} ${projectClient(state,state.projects.find(p=>p.id===i.projectId)).name}`.toLowerCase().includes(query.toLowerCase()));return `${heading('Invoices','Track issued invoices and recorded payments.',btn(icon('download')+'Export CSV','export'))}${metrics()}${controls([['all','All invoices'],['outstanding','Outstanding'],['overdue','Overdue'],['paid','Paid']],'Find an invoice…')}<div class="card table-wrap"><table class="data-table"><thead><tr><th>Invoice / Client</th><th>Status</th><th>Amount</th><th>Due date</th><th></th></tr></thead><tbody>${list.map(i=>{const p=state.projects.find(p=>p.id===i.projectId);const c=projectClient(state,p);return `<tr><td><button class="name-cell" data-action="invoice" data-id="${i.id}"><span><strong>${i.number}</strong><small>${esc(i.clientName||c.name)}</small></span></button></td><td>${badge(invoiceStatus(i))}</td><td>${money(i.amount)}</td><td class="muted">${date(i.due)}</td><td><button class="icon-btn" data-action="invoice" data-id="${i.id}" aria-label="Open ${i.number}">${icon('arrow')}</button></td></tr>`}).join('')}</tbody></table>${list.length?'':'<div class="empty">No invoices match this view.</div>'}</div><div class="bottom-note">${icon('info')}Sample invoices only. No payments are processed.</div>`}
function workflowsPage(){return `${heading('Workflows','Review the triggers and actions in your workspace.',btn(icon('sparkles')+'Configure defaults','setup','','primary'))}<div class="notice">Explore how a proposal becomes a deposit invoice and an active project. These sample workflows run only inside this prototype.</div><div class="flow-grid">${state.workflows.map((w,index)=>`<article class="card flow-card"><div class="flow-top"><span class="flow-icon">${icon(index?'mail':'workflows')}</span>${index===0?`<button class="toggle ${w.enabled?'on':''}" data-action="toggle-workflow" data-id="${w.id}" role="switch" aria-checked="${w.enabled}" aria-label="Enable deposit workflow"></button>`:'<span class="badge">Preview</span>'}</div><h2>${esc(w.name)}</h2><p>${esc(w.description)}</p><div class="flow-steps">${(index?['Call completed','Draft proposal','Your review']:['Proposal accepted','Deposit invoice','Payment received']).map((s,i)=>`${i?icon('arrow'):''}<span>${s}</span>`).join('')}</div><div class="footer-actions"><span class="badge ${w.enabled?'active':''}"><i></i>${w.enabled?'Active in demo':index?'Planned capability':'Paused'}</span><button class="text-btn" data-action="workflow" data-id="${w.id}">View workflow ${icon('arrow')}</button></div></article>`).join('')}</div><div class="section">${activity()}</div>`}
function render(){if(!['overview','clients','projects','invoices','workflows'].includes(page))page='overview';shell();document.querySelector('#main').innerHTML=({overview,clients:clientsPage,projects:projectsPage,invoices:invoicesPage,workflows:workflowsPage}[page])();document.title=`Thrive — ${page[0].toUpperCase()+page.slice(1)}`}
function projectDetail(id){return journey.projectDetail(id);}
function clientDetail(id){return journey.clientDetail(id);}
function proposalDetail(id){return journey.proposalDetail(id);}
function invoiceDetail(id){const i=state.invoices.find(i=>i.id===id),p=state.projects.find(p=>p.id===i.projectId),c=projectClient(state,p);open('Invoice',`<div class="dialog-body"><div class="code-label">${i.number} · SAMPLE INVOICE</div><div class="invoice-total">${money(i.amount)}</div>${badge(invoiceStatus(i))}<div class="section"><div class="list-line"><span class="muted">Billed to</span><strong>${esc(i.clientName||c.name)}</strong></div><div class="list-line"><span class="muted">Project</span><span>${esc(i.projectName||p.name)}</span></div><div class="list-line"><span class="muted">Payment for</span><span>${esc(i.label||i.kind[0].toUpperCase()+i.kind.slice(1))}</span></div><div class="list-line"><span class="muted">Due</span><span>${date(i.due)}</span></div><div class="list-line"><span class="muted">Remaining</span><strong>${money(i.amount-i.paid)}</strong></div></div><div class="section notice">This is a prototype invoice. Recording a sample payment updates the connected project and overview; it does not move money.</div></div>`,{drawer:true,footer:i.paid<i.amount?btn('Record sample payment '+icon('check'),'pay',`data-id="${id}"`,'accent'):btn('View project '+icon('arrow'),'project',`data-id="${p.id}"`)})}
function projectForm(clientId){open('New project',`<form id="project-form"><div class="dialog-body"><label class="field">Project name<input name="name" placeholder="e.g. Juniper brand identity" maxlength="100" required autofocus></label><label class="field">Client<select name="clientId" required>${state.clients.filter(c=>!c.archived).map(c=>`<option value="${c.id}" ${c.id===clientId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="field-row"><label class="field">Project fee (USD)<input name="budget" type="number" min="1" step=".01" placeholder="3000" required></label><label class="field">Target date<input name="due" type="date" required></label></div><label class="field">Service<input name="service" value="${esc(state.settings.service||'Brand identity')}" maxlength="80"></label><div class="notice">Your setup: ${state.settings.deposit}% deposit · ${state.settings.phases.map(esc).join(' → ')}. You can adjust your setup for future projects.</div><div class="form-error" role="alert"></div></div><div class="dialog-footer">${btn('Cancel','close')}<button class="btn primary" type="submit">Create project ${icon('arrow')}</button></div></form>`)}
function clientForm(id){return journey.clientForm(id);}
function logTime(id){open('Log time',`<form id="time-form"><div class="dialog-body"><label class="field">Project<select name="projectId">${state.projects.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="field-row"><label class="field">Hours<input name="hours" type="number" min="0.1" max="24" step="0.1" placeholder="1.5" required></label><label class="field">Date<input name="date" type="date" value="${today()}" required></label></div><label class="field">What did you work on?<input name="note" placeholder="e.g. Logo concepts" maxlength="200" required></label><div class="form-error" role="alert"></div></div><div class="dialog-footer">${btn('Cancel','close')}<button class="btn primary" type="submit">Save time entry ${icon('check')}</button></div></form>`)}
function setup(){open('Configure defaults',`<div class="dialog-body"><div class="setup-intro">${icon('sparkles')}<h1>Configure your workspace</h1><p>Describe your services and payment terms.</p></div><label class="field">Tell us about your business<textarea id="setup-prompt" rows="5">${esc(state.settings.description)}</textarea></label><div class="prompt-examples"><button data-action="example" data-kind="design">I’m a brand designer</button><button data-action="example" data-kind="web">I build websites</button><button data-action="example" data-kind="consult">I’m a consultant</button></div><div class="notice"><strong>Guided setup preview</strong><br>This prototype recognizes a deposit percentage and a few service types. You’ll review and edit the suggested setup. Live AI is part of the next build.</div><div class="form-error" role="alert"></div></div>`,{footer:btn('Preview my setup '+icon('arrow'),'suggest','','accent')})}
function setupPreview(){open('Your suggested setup',`<form id="setup-form"><div class="dialog-body"><div class="ai-eyebrow">${icon('sparkles')} PROPOSED CHANGES</div><h1>Review your defaults</h1><p>These changes apply to future projects only.</p><div class="notice">Deposit: ${state.settings.deposit}% → ${setupDraft.deposit}%<br>Phases: ${state.settings.phases.map(esc).join(', ')} → ${setupDraft.phases.map(esc).join(', ')}<br>Deposit workflow: ${state.workflows[0].enabled?'already active':'will be enabled'}</div>${setupDraft.unsupported?'<div class="notice">Your description mentions capabilities this prototype cannot configure yet. This preview covers fixed-fee projects and deposit invoicing only.</div>':''}<div class="field-row"><label class="field">Deposit percentage<input name="deposit" type="number" min="1" max="100" value="${setupDraft.deposit}" required></label><label class="field">Billing style<input value="Fixed fee + deposit" readonly></label></div><label class="field">Project phases, separated by commas<input name="phases" value="${esc(setupDraft.phases.join(', '))}" required maxlength="180"></label><div class="preview-step"><span>01</span> Create a client and project ${icon('check')}</div><div class="preview-step"><span>02</span> Review a proposal before acceptance ${icon('check')}</div><div class="preview-step"><span>03</span> Create the deposit invoice on acceptance ${icon('check')}</div><div class="preview-step"><span>04</span> Start delivery when the deposit is paid ${icon('check')}</div><p class="hint">Existing project fees, phases, and accepted terms stay intact. Enabling this setup activates the sample deposit workflow. Email sending and calendar integration are not connected.</p><div class="form-error" role="alert"></div></div><div class="dialog-footer">${btn('Back','setup')}<button type="submit" class="btn accent">Use this setup ${icon('check')}</button></div></form>`)}
function workflowDetail(id){const w=state.workflows.find(w=>w.id===id);open('Workflow details',`<div class="dialog-body"><span class="flow-icon" style="width:fit-content">${icon('workflows')}</span><h1>${esc(w.name)}</h1><p>${esc(w.description)}</p>${(id==='w1'?['A proposal is accepted','Create one deposit invoice using the project’s saved terms','Wait for the deposit payment','Move the project into active delivery']:['Mark the discovery call complete','Use the inquiry and meeting notes to draft a proposal','Prepare an accompanying email','Wait for your review before sending']).map((s,i)=>`<div class="preview-step"><span>0${i+1}</span>${s}</div>`).join('')}<div class="section notice">${id==='w1'?'Try this with Paper & Pine’s proposal. Repeating an acceptance or payment action won’t create duplicates.':'This is a preview of a planned workflow. Email and calendar integrations will be added in a later milestone.'}</div></div>`,{footer:id==='w1'?btn('Choose a project '+icon('arrow'),'navigate',`data-page="projects"`,'primary'):btn('Close','close')})}
function portal(id='p1'){return journey.portal(id);}
function business(){open('Your workspace',`<form id="business-form"><div class="dialog-body"><label class="field">Your name<input name="name" value="${esc(state.settings.name)}" required maxlength="80"></label><label class="field">Business name<input name="business" value="${esc(state.settings.business)}" required maxlength="80"></label><div class="notice">Demo workspace · USD · Changes saved in this browser.</div><button type="button" class="text-btn" data-action="reset-preview">Reset sample data</button></div><div class="dialog-footer">${btn('Close','close')}<button class="btn primary" type="submit">Save details</button></div></form>`)}
function search(){open('Search workspace',`<div class="dialog-body"><input id="global-search" class="filter-input full-width" placeholder="Search clients, projects, or invoices…" aria-label="Search clients, projects, or invoices" autofocus></div><div id="search-results" class="search-results"></div>`);searchResults('')}
function searchResults(q){const needle=q.toLowerCase();const results=[...state.clients.map(c=>({name:c.name,type:'Client',action:'client',id:c.id})),...state.projects.map(p=>({name:p.name,type:'Project',action:'project',id:p.id})),...state.invoices.map(i=>({name:i.number+' · '+money(i.amount),type:'Invoice',action:'invoice',id:i.id}))].filter(r=>r.name.toLowerCase().includes(needle)).slice(0,10);document.querySelector('#search-results').innerHTML=results.map(r=>`<button class="search-result" data-action="${r.action}" data-id="${r.id}">${icon(r.action==='client'?'clients':r.action==='invoice'?'invoices':'projects')}${esc(r.name)}<small>${r.type}</small></button>`).join('')||'<div class="empty">No matches. Try a client or project name.</div>'}
const journey=createJourneyUI({getState:()=>state,open,btn,icon,esc,badge,avatar,date,save,render,toast,dialog});
document.addEventListener('click',e=>{
 if(e.target.closest('.skip')){e.preventDefault();document.querySelector('#main').focus();return;}
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 try{
 if(journey.handleClick(a,el))return;
 if(a==='close')dialog.close();
 else if(a==='theme'){const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('thrive-theme',t)}catch{}}
 else if(a==='project')projectDetail(id);else if(a==='client')clientDetail(id);else if(a==='invoice')invoiceDetail(id);else if(a==='proposal')proposalDetail(id);
 else if(a==='new-project')projectForm(el.dataset.client);else if(a==='new-client')clientForm();else if(a==='log-time')logTime(id);else if(a==='setup')setup();else if(a==='business')business();else if(a==='portal')portal(id);
 else if(a==='filter'){filter=el.dataset.filter;render()}
 else if(a==='navigate'){dialog.close();go(el.dataset.page)}
 else if(a==='deposit'){const invoice=generateDeposit(state,id);save();render();invoiceDetail(invoice.id);toast('Deposit invoice ready.')}
 else if(a==='pay'){recordPayment(state,id);save();render();invoiceDetail(id);toast('Sample payment recorded.')}
 else if(a==='toggle-workflow'){const w=state.workflows.find(w=>w.id===id);w.enabled=!w.enabled;save();render();toast(w.enabled?'Deposit workflow enabled.':'Deposit workflow paused. You can still create invoices manually.')}
 else if(a==='workflow')workflowDetail(id);
 else if(a==='suggest'){const text=document.querySelector('#setup-prompt').value.trim();if(text.length<10)throw new Error('Describe your services and payment terms.');setupDraft=suggestSetup(text);setupPreview()}
 else if(a==='example'){document.querySelector('#setup-prompt').value=({design:'I’m a brand designer. I take 50% upfront, work in discovery, design, and handoff, and review every proposal.',web:'I build websites. I take a 40% deposit and work through discovery, design, development, and launch.',consult:'I’m a strategy consultant. I take 30% upfront, then move through discovery, strategy, and recommendations.'})[el.dataset.kind]}
 else if(a==='search')search();
 else if(a==='reset-preview')open('Reset the demo?', '<div class="dialog-body"><p>This restores the original sample workspace and removes changes made in this browser. Your appearance preference is kept.</p></div>',{footer:btn('Keep my changes','close')+btn('Reset sample data','reset-data','','primary')});
 else if(a==='reset-data'){state=seed();save();dialog.close();render();toast('Sample data restored.')}
 else if(a==='export'){const rows=[['Invoice','Client','Project','Amount USD','Paid USD','Due','Status'],...state.invoices.map(i=>{const p=state.projects.find(p=>p.id===i.projectId);return [i.number,projectClient(state,p).name,p.name,(i.amount/100).toFixed(2),(i.paid/100).toFixed(2),i.due,invoiceStatus(i)]})];const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const link=document.createElement('a');link.href=url;link.download='thrive-sample-invoices.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your sample invoice export is ready.')}
 }catch(err){error(err.message)}
});
document.addEventListener('submit',e=>{
 if(!e.target.closest('dialog'))return;e.preventDefault();const f=new FormData(e.target),values=Object.fromEntries(f);
 try{
 if(journey.handleSubmit(e.target,values,e.submitter?.value))return;
 if(e.target.id==='project-form'){const p=createProject(state,{...values,budget:Math.round(Number(values.budget)*100)});save();render();projectDetail(p.id);toast('Project created.')}
 if(e.target.id==='time-form'){const hours=Number(values.hours);if(!Number.isFinite(hours)||hours<=0||hours>24||!state.projects.some(p=>p.id===values.projectId))throw new Error('Choose a project and enter between 0.1 and 24 hours.');state.time.push({id:uid(),...values,hours});save();render();dialog.close();toast(`${hours} hours saved to your project.`)}
 if(e.target.id==='setup-form'){const deposit=Number(values.deposit),phases=values.phases.split(',').map(s=>s.trim()).filter(Boolean);if(!Number.isInteger(deposit)||deposit<1||deposit>100||!phases.length||phases.length>8)throw new Error('Choose a deposit from 1–100% and between 1 and 8 phases.');state.settings={...state.settings,deposit,phases,description:setupDraft.description,service:setupDraft.service,review:true};state.workflows[0].enabled=true;addActivity(state,'Workspace defaults updated',`${deposit}% deposit · ${phases.join(', ')}`,'project');save();render();dialog.close();toast('Setup saved. Your next project will use these defaults.')}
 if(e.target.id==='business-form'){if(!values.name.trim()||!values.business.trim())throw new Error('Enter your name and business name.');state.settings={...state.settings,name:values.name.trim(),business:values.business.trim()};save();render();dialog.close();toast('Workspace details saved.')}
 }catch(err){error(err.message)}
});
document.addEventListener('input',e=>{journey.handleInput(e.target);if(e.target.id==='list-search'){const cursor=e.target.selectionStart;query=e.target.value;render();const input=document.querySelector('#list-search');input.focus();input.setSelectionRange(cursor,cursor)}if(e.target.id==='global-search')searchResults(e.target.value)});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search()}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'overview';filter='all';query='';render();document.querySelector('#main').focus()});
render();
